const columns={de:0,en:1,cs:2,fr:3,ja:4,it:5};
const dictionary=new Map(messages.map(row=>[row[0],row]));
let language='de';
export const currentLocale=()=>language;
export function t(source,params={}) {
  const row=dictionary.get(source);let text=row?row[columns[language]]:source;
  return String(text).replace(/\{(\w+)\}/g,(m,key)=>params[key]===undefined?m:String(params[key]));
}
export function localizedError(value){
  const text=String(value);
  const missingVoice=text.match(/^Keine männliche Edge-Stimme für (.+) verfügbar\.$/);if(missingVoice)return t('Keine männliche Edge-Stimme für {locale} verfügbar.',{locale:missingVoice[1]});
  const http=text.match(/^(HTTP \d+: )(.*)$/s);if(http)return http[1]+localizedError(http[2]);
  const cooldown=text.match(/^Bitte noch (\d+) Sekunden warten\.$/);if(cooldown)return t('Bitte noch {seconds} Sekunden warten.',{seconds:cooldown[1]});
  const separator=text.indexOf(': ');if(separator>0&&dictionary.has(text.slice(0,separator)))return t(text.slice(0,separator))+text.slice(separator).replace('Zwischenablage im Fenster einfügen.',t('Zwischenablage im Fenster einfügen.'));
  return t(text);
}
const records=[];
export function captureStaticText(){
  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
  while(walker.nextNode()) {const node=walker.currentNode;const key=node.textContent.trim();if(dictionary.has(key))records.push({node,key,prefix:node.textContent.match(/^\s*/)[0],suffix:node.textContent.match(/\s*$/)[0]});}
  for(const node of document.querySelectorAll('[placeholder],[title],[aria-label]')) for(const attr of ['placeholder','title','aria-label']) {const key=node.getAttribute(attr);if(dictionary.has(key))records.push({node,key,attr});}
}
export function applyLocale(locale){
  language=Object.hasOwn(locales,locale)?locale:'de';document.documentElement.lang=language;
  for(const r of records)if(r.node.isConnected){if(r.attr)r.node.setAttribute(r.attr,t(r.key));else r.node.textContent=r.prefix+t(r.key)+r.suffix;}
  // Expose localized CSS-generated labels without putting translations in stylesheets.
  document.documentElement.style.setProperty('--text-language-label',JSON.stringify(t('Textsprache')));
}
